package com.mavric.health.support;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.*;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.*;
import com.mavric.health.persistence.sqlserver.*;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Real controller and store, modeled executor/manager. No HTTP server, SQL or actual permissions. */
class SupportControllerSqlServerTest {
 static final String ID="aa000000-0000-4000-8000-000000000001";
 final SqlServerExecutor executor=mock(SqlServerExecutor.class);final ModelTransactionManager manager=new ModelTransactionManager();final SqlServerSupportStore store=new SqlServerSupportStore(executor,manager);final Access access=mock(Access.class);final AccountLifecycleService lifecycle=mock(AccountLifecycleService.class);final Sql sql=mock(Sql.class);final SupportController controller=new SupportController(store,access,lifecycle);final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/support");
 final List<SqlServerContext> contexts=new ArrayList<>();final List<SqlServerProcedure> calls=new ArrayList<>();final List<List<Object>> bindings=new ArrayList<>();
 void actor(String role,boolean tenant){var actor=new Actor(ID,"Synthetic","qa@example.test",tenant?ID:null,List.of(role),"a".repeat(64));doReturn(actor).when(access).actor();request.setAttribute("health.actor",actor);if(tenant)request.setAttribute("health.tenant",new TenantRef(ID,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of()));else request.removeAttribute("health.tenant");TraceContext.REQUEST.set(request);}
 SupportControllerSqlServerTest(){when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var sp=inv.<SqlServerProcedure>getArgument(0);calls.add(sp);contexts.add(inv.getArgument(1));var values=Arrays.asList(((Object[])inv.getRawArguments()[2]).clone());bindings.add(values);assertEquals(SqlServerContext.Scope.REQUEST,inv.<SqlServerContext>getArgument(1).scope());if(sp==SqlServerProcedure.SUPPORT_CREATE)return new SqlServerExecutor.Result(List.of(),List.of());if(sp==SqlServerProcedure.SUPPORT_LIST)return new SqlServerExecutor.Result(List.of(List.of()),List.of());var row=new LinkedHashMap<String,Object>();row.put("id",ID);row.put("tenantId",request.getAttribute("health.tenant")==null?null:ID);row.put("actorId",ID);row.put("reference","Synthetic");row.put("email","qa@example.test");row.put("subject","Synthetic");row.put("message","Synthetic");row.put("status","OPEN");row.put("priority","NORMAL");row.put("revision",1);row.put("createdAt","2026-11-04T00:00:00Z");row.put("updatedAt","2026-11-04T00:00:00Z");List<Map<String,Object>> comments=List.of();if(sp==SqlServerProcedure.SUPPORT_STEP){row.put("status",values.get(2));row.put("priority",values.get(3));row.put("revision",2);if(values.get(5)!=null)comments=List.of(Map.of("id",values.get(4),"message",values.get(5),"createdAt","2026-11-04T00:00:00Z","actorName","Synthetic"));}return new SqlServerExecutor.Result(List.of(List.of(row),comments),List.of());});}
 @AfterEach void cleanup(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 @Test void platformSadSopAndEveryTenantRoleCanReadOwnSupport(){for(String role:List.of("SAD","SOP")){actor(role,false);assertEquals(List.of(),controller.list());assertEquals(List.of(),((Map<?,?>)controller.get(ID)).get("comments"));}for(String role:List.of("ADM","AUD","PRO","REC","PAC","RES")){actor(role,true);assertEquals(List.of(),controller.list());assertEquals(ID,((Map<?,?>)controller.get(ID)).get("id"));}verifyNoInteractions(sql,lifecycle);}
 @Test void missingRequestActorMismatchHostTypeAndPlatformRoleNeverQuery(){assertEquals(500,assertThrows(ApiException.class,controller::list).status);actor("PRO",true);doThrow(new ApiException(401,"UNAUTHENTICATED","Safe")).when(access).actor();assertEquals(401,assertThrows(ApiException.class,controller::list).status);actor("PRO",false);assertEquals(403,assertThrows(ApiException.class,controller::list).status);actor("PRO",true);request.setAttribute("health.actor","forged");assertEquals(403,assertThrows(ApiException.class,controller::list).status);actor("PRO",true);request.setAttribute("health.tenant","forged");assertEquals(500,assertThrows(ApiException.class,controller::list).status);verifyNoInteractions(executor);}
 @Test void writesRequireInternalRequestBeforeEffects(){assertEquals(500,assertThrows(ApiException.class,()->controller.create(null,null)).status);assertEquals("DATABASE_ERROR",assertThrows(ApiException.class,()->controller.step("bad",null)).code);verifyNoInteractions(executor,lifecycle,access,sql);}
 @Test void errorsNoFallbackAndForgedClientDataDoesNotSelectAuthority(){actor("PAC",true);request.addHeader("X-Tenant-Id","forged");request.addHeader("X-Roles","SAD");request.setContent("forged body".getBytes());assertEquals(List.of(),controller.list());doThrow(new RuntimeException(new java.sql.SQLException("private",null,51002))).when(executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->controller.get(ID));assertEquals(404,e.status);assertFalse(e.toString().contains("private"));verifyNoInteractions(sql,lifecycle);}
 @Test void minimalSpringSelectsLegacyWithoutDatasource(){doReturn(new Actor(ID,"Synthetic","qa@example.test",null,List.of("SAD"),"a".repeat(64))).when(access).actor();when(sql.rows(anyString(),any(Object[].class))).thenReturn(List.of());try(var context=new AnnotationConfigApplicationContext()){context.registerBean(Sql.class,()->sql);context.registerBean(Access.class,()->access);context.registerBean(AccountLifecycleService.class,()->lifecycle);context.registerBean(SupportController.class);context.refresh();assertEquals(List.of(),context.getBean(SupportController.class).list());verify(sql).rows(anyString(),any(Object[].class));assertEquals(0,context.getBeanNamesForType(SqlServerSupportStore.class).length);assertEquals(0,context.getBeanNamesForType(javax.sql.DataSource.class).length);}verifyNoInteractions(executor);}
 static SupportController.Ticket payload(){return new SupportController.Ticket("qa@example.test","Synthetic \u4e2d\ud83e\uddb7","Synthetic \u00e1 message","NORMAL");}
 @Test void publicCreateAnonymousPlatformTenantAndSignedActorHaveExactReceiptAndOneRate(){for(int mode=0;mode<3;mode++){reset(lifecycle,access);request.removeAttribute("health.actor");request.removeAttribute("health.tenant");TraceContext.REQUEST.set(request);if(mode==1)request.setAttribute("health.tenant",new TenantRef(ID,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of()));if(mode==2)actor("PAC",true);var receipt=(Map<?,?>)controller.create(payload(),request);assertEquals(Set.of("reference","status","message","provider","website"),receipt.keySet());assertEquals("OPEN",receipt.get("status"));assertEquals("Solicitud registrada. Conserva tu referencia.",receipt.get("message"));assertEquals("Mavric Technologies",receipt.get("provider"));assertEquals("https://mavrictec.com",receipt.get("website"));assertTrue(((String)receipt.get("reference")).matches("MVT-[0-9A-F]{8}-[0-9A-F]{3}"));verify(lifecycle,times(1)).rate("127.0.0.1","support");if(mode<2)verifyNoInteractions(access);assertEquals(SqlServerProcedure.SUPPORT_CREATE,calls.getLast());assertEquals(mode==0?null:ID,contexts.getLast().tenantId());assertEquals(mode==2?ID:null,contexts.getLast().actorId());var args=bindings.getLast();assertEquals(args.getFirst(),UUID.fromString((String)args.getFirst()).toString());var json=new tools.jackson.databind.ObjectMapper().readTree((String)args.get(2));assertEquals(4,json.size());assertEquals(payload().message(),json.get("message").asText());assertFalse(receipt.toString().contains("qa@example.test"));assertFalse(receipt.containsKey("id"));}}
 @Test void publicCreateRequestValidationBeforeRateAnd429BeforeSp(){TraceContext.REQUEST.set(request);assertEquals(500,assertThrows(ApiException.class,()->controller.create(payload(),new MockHttpServletRequest())).status);request.setAttribute("health.tenant","forged");assertEquals(500,assertThrows(ApiException.class,()->controller.create(payload(),request)).status);request.removeAttribute("health.tenant");verifyNoInteractions(lifecycle,executor,access);doThrow(new ApiException(429,"RATE_LIMIT","Safe")).when(lifecycle).rate(anyString(),eq("support"));assertEquals(429,assertThrows(ApiException.class,()->controller.create(payload(),request)).status);verify(lifecycle,times(1)).rate(anyString(),eq("support"));verifyNoInteractions(executor,access);}
 @Test void publicSignedActorMustMatchAccessAndStepUsesSingleSpTwoResultsets(){actor("PRO",true);request.setAttribute("health.actor",new Actor(ID,"Different","qa@example.test",ID,List.of("PRO"),"a".repeat(64)));assertEquals(403,assertThrows(ApiException.class,()->controller.create(payload(),request)).status);verifyNoInteractions(lifecycle,executor);for(boolean tenant:List.of(false,true)){actor(tenant?"PAC":"SOP",tenant);var out=(Map<?,?>)controller.step(ID,new SupportController.Step(1,tenant?"OPEN":"IN_PROGRESS","NORMAL",tenant?"Synthetic comment":null));assertEquals(2,out.get("revision"));assertEquals(tenant?1:0,((List<?>)out.get("comments")).size());assertEquals(SqlServerProcedure.SUPPORT_STEP,calls.getLast());var args=bindings.getLast();assertEquals(6,args.size());assertEquals(ID,args.getFirst());assertEquals(1,args.get(1));assertEquals(args.get(4),UUID.fromString((String)args.get(4)).toString());}assertFalse(calls.contains(SqlServerProcedure.SUPPORT_DETAIL));verifyNoInteractions(lifecycle);}

 @Test void publicMissingAuthenticationAndNullPayloadRejectBeforeRateWrite(){TraceContext.REQUEST.set(request);assertEquals(400,assertThrows(ApiException.class,()->controller.create(null,request)).status);verifyNoInteractions(access,lifecycle,executor);actor("PRO",true);assertEquals(400,assertThrows(ApiException.class,()->controller.step(ID,null)).status);doThrow(new ApiException(401,"UNAUTHENTICATED","Safe")).when(access).actor();assertEquals(401,assertThrows(ApiException.class,()->controller.create(payload(),request)).status);verifyNoInteractions(lifecycle,executor,sql);}

}
